def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents
    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return min(my_status['budget'], int(DAILY_SALARY * 0.4))

    # Read yesterday bids for immediate reaction
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            prev_bids.append(float(b))

    # Compute pressure signals
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Our urgency
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])

    # Supply-based urgency: if supply is near our requirement, winning is critical.
    # If supply is high, we can tolerate slightly lower bids.
    supply_ratio = supply / float(WATER_REQ)

    # Baseline bid: aim near the market average but slightly above when supply is tight.
    # Use explicit ints for safety.
    if supply_ratio <= (float(MIN_SUPPLY) / float(WATER_REQ)):
        baseline = max(DAILY_SALARY * 0.55, avg_prev_bid * 1.05)
    else:
        baseline = max(DAILY_SALARY * 0.5, avg_prev_bid * 0.95)

    # If someone overbid aggressively yesterday, nudge up to prevent them from locking water.
    # But avoid chasing extreme bids unless our hp is very low.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if hp > 3:
            bid = baseline * 1.15
        else:
            bid = baseline * 1.35
    else:
        # Mild competitive environment: keep bid restrained.
        if hp <= 2:
            bid = baseline * 1.45
        elif hp <= 3:
            bid = baseline * 1.25
        else:
            bid = baseline

    # Convert to integer bid and clamp to budget.
    bid_int = int(bid)
    if bid_int < 0:
        bid_int = 0

    # Never bid more than we can afford.
    bid_int = min(bid_int, int(budget))

    # If budget is too small, still bid something proportional to survival.
    if bid_int <= 0:
        bid_int = min(int(budget), int(DAILY_SALARY * 0.2))

    return bid_int

